<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import http from '../api/http';import PublicState from './PublicState.vue';const route=useRoute(),loading=ref(true),error=ref(''),item=ref<any>(null),schedules=ref<any[]>([]);async function load(){loading.value=true;try{const id=route.params.id;const [doctor,plan]=await Promise.all([http.get(`/public/doctors/${id}`),http.get(`/public/doctors/${id}/schedules`,{params:{page:1,pageSize:14}})]);item.value=doctor.data.data;schedules.value=plan.data.data.records;}catch(e:any){error.value=e.message??'医生不存在或未发布';}finally{loading.value=false;}}onMounted(load);watch(()=>route.params.id,load);</script><template><section class="page"><PublicState :loading="loading" :error="error" :empty="!item"><article class="detail"><h1>{{item.name}} <small>{{item.title}}</small></h1><p>{{item.departments.map((x:any)=>x.name).join('、')}}</p><h2>个人简介</h2><p>{{item.profile||'暂无公开简介'}}</p><h2>擅长领域</h2><p>{{item.specialties.map((x:any)=>x.name).join('、')||item.specialtySummary||'待完善'}}</p><h2>近期出诊</h2><p v-if="!schedules.length">暂无已发布的未来出诊。</p><router-link v-else v-for="schedule in schedules" :key="schedule.id" class="detail" :to="`/booking?doctorId=${route.params.id}&scheduleId=${schedule.id}`">{{schedule.scheduleDate}} {{schedule.sessionName}} · {{schedule.startTime}}-{{schedule.endTime}} · {{schedule.outpatientDepartmentName}} · 剩余 {{schedule.availableQuota}} 号</router-link><h2>就诊提示</h2><p>{{item.consultationNotice||'请选择出诊时间进入预约。'}}</p></article></PublicState></section></template>
